INSERT INTO news (date, lang, title, text) VALUES
 ('2026-11-18', 'es', 'Juegos arreglados en la 3.0', 'Arreglos de juegos que ya trae la 3.0: Conker''s Bad Fur Day ya no muestra un frame viejo encima tras la pausa, Banjo-Kazooie ya no se pone negro bajo el agua y Dinosaur Planet ya no da tirones a 60 FPS.'),
 ('2026-11-18', 'en', 'Games fixed in 3.0', 'Game fixes 3.0 already brings: Conker''s Bad Fur Day no longer shows an old frame on top after the pause, Banjo-Kazooie no longer turns black under water and Dinosaur Planet no longer stutters at 60 FPS.'),
 ('2026-11-18', 'pt', 'Jogos corrigidos na 3.0', 'Correções de jogos que a 3.0 já traz: Conker''s Bad Fur Day não mostra mais um quadro antigo por cima após a pausa, Banjo-Kazooie não fica mais preto debaixo d''água e Dinosaur Planet não engasga mais a 60 FPS.'),
 ('2026-11-18', 'fr', 'Jeux corrigés dans la 3.0', 'Corrections de jeux déjà dans la 3.0 : Conker''s Bad Fur Day n''affiche plus une vieille image par-dessus après la pause, Banjo-Kazooie ne devient plus noir sous l''eau et Dinosaur Planet ne saccade plus à 60 FPS.'),
 ('2026-11-18', 'it', 'Giochi corretti nella 3.0', 'Correzioni di giochi già presenti nella 3.0: Conker''s Bad Fur Day non mostra più un vecchio fotogramma sopra dopo la pausa, Banjo-Kazooie non diventa più nero sott''acqua e Dinosaur Planet non scatta più a 60 FPS.'),
 ('2026-11-18', 'de', 'Behobene Spiele in 3.0', 'Spielkorrekturen, die 3.0 schon enthält: Conker''s Bad Fur Day zeigt nach der Pause kein altes Bild mehr darüber, Banjo-Kazooie wird unter Wasser nicht mehr schwarz und Dinosaur Planet ruckelt bei 60 FPS nicht mehr.'),
 ('2026-11-18', 'ru', 'Исправленные игры в 3.0', 'Исправления игр, которые уже есть в 3.0: Conker''s Bad Fur Day больше не показывает старый кадр поверх после паузы, Banjo-Kazooie больше не чернеет под водой, а Dinosaur Planet больше не дёргается на 60 FPS.'),
 ('2026-11-18', 'es', 'Próxima versión (próximamente)', 'Wave Race 64, Star Wars: Shadows of the Empire y Army Men: Air Combat ya se ven bien. En línea: se acabaron las desincronizaciones entre consolas, vibran todos los jugadores y si te quedas solo sigues con tu personaje. La vibración de los avisos ya no se queda pegada.'),
 ('2026-11-18', 'en', 'Next version (coming soon)', 'Wave Race 64, Star Wars: Shadows of the Empire and Army Men: Air Combat now look right. Online: no more desyncs between consoles, every player''s controller vibrates and if you are left alone you keep your character. Notification vibration no longer gets stuck.'),
 ('2026-11-18', 'pt', 'Próxima versão (em breve)', 'Wave Race 64, Star Wars: Shadows of the Empire e Army Men: Air Combat agora aparecem certos. Online: acabaram as dessincronizações entre consoles, todos os jogadores vibram e se você ficar sozinho continua com seu personagem. A vibração dos avisos não fica mais presa.'),
 ('2026-11-18', 'fr', 'Prochaine version (bientôt)', 'Wave Race 64, Star Wars: Shadows of the Empire et Army Men: Air Combat s''affichent bien. En ligne : plus de désynchronisation entre consoles, tous les joueurs vibrent et si vous restez seul, vous gardez votre personnage. La vibration des notifications ne reste plus bloquée.'),
 ('2026-11-18', 'it', 'Prossima versione (presto)', 'Wave Race 64, Star Wars: Shadows of the Empire e Army Men: Air Combat ora si vedono bene. Online: niente più desincronizzazioni tra console, vibrano tutti i giocatori e se resti solo tieni il tuo personaggio. La vibrazione degli avvisi non resta più bloccata.'),
 ('2026-11-18', 'de', 'Nächste Version (bald)', 'Wave Race 64, Star Wars: Shadows of the Empire und Army Men: Air Combat sehen jetzt richtig aus. Online: keine Desyncs mehr zwischen Konsolen, alle Spieler spüren die Vibration und wer allein bleibt, behält seine Figur. Die Vibration der Hinweise bleibt nicht mehr hängen.'),
 ('2026-11-18', 'ru', 'Следующая версия (скоро)', 'Wave Race 64, Star Wars: Shadows of the Empire и Army Men: Air Combat теперь выглядят правильно. Онлайн: больше нет рассинхронизации консолей, вибрация у всех игроков, а оставшись один, вы сохраняете своего персонажа. Вибрация уведомлений больше не залипает.');
